export function getHadithBook(id: string): HadithBook | undefined {
  return HADITH_BOOKS.find((b) => b.id.toLowerCase() === id.toLowerCase());
}

export function getHadithChapter(bookId: string, chapterId: number): HadithChapter | undefined {
  const book = getHadithBook(bookId);
  if (!book) return undefined;
  return book.chapters.find((c) => c.id === chapterId);
}
